class Doc:
    def __init__(self):
        self._text = ''
        self._done = []
        self._undone = []
        self._group_stack = []

    def text(self):
        return self._text

    def begin_group(self):
        self._group_stack.append([])

    def end_group(self):
        if not self._group_stack:
            raise RuntimeError('end_group without begin_group')
        edits = self._group_stack.pop()
        if not self._group_stack:
            self._done.append(edits)

    def _apply(self, edit):
        kind, pos, s = edit
        if kind == 'insert':
            self._text = self._text[:pos] + s + self._text[pos:]
        else:
            self._text = self._text[:pos] + self._text[pos + len(s):]

    def _invert(self, edit):
        kind, pos, s = edit
        return ('delete' if kind == 'insert' else 'insert', pos, s)

    def _record(self, edit):
        if self._group_stack:
            self._group_stack[-1].append(edit)
        else:
            self._done.append([edit])
            self._undone = []

    def insert(self, pos, s):
        if pos < 0 or pos > len(self._text):
            raise IndexError(pos)
        edit = ('insert', pos, s)
        self._apply(edit)
        self._record(edit)

    def delete(self, pos, n):
        if pos < 0 or pos + n > len(self._text):
            raise IndexError(pos)
        edit = ('delete', pos, self._text[pos:pos + n])
        self._apply(edit)
        self._record(edit)

    def undo(self):
        if self._group_stack:
            raise RuntimeError('undo while a group is open')
        if not self._done:
            return
        step = self._done.pop()
        for edit in reversed(step):
            self._apply(self._invert(edit))
        self._undone.append(step)

    def redo(self):
        if self._group_stack:
            raise RuntimeError('redo while a group is open')
        if not self._undone:
            return
        step = self._undone.pop()
        for edit in step:
            self._apply(edit)
        self._done.append(step)

